import numpy as np, json
def solve(inp):
    inp=np.array(inp); H,W=inp.shape
    vals,counts=np.unique(inp,return_counts=True)
    bg=int(vals[np.argmax(counts)])
    mv=rrow=ccol=None
    for v in vals:
        if v==bg: continue
        rows=np.where((inp==v).all(axis=1))[0]
        cols=np.where((inp==v).all(axis=0))[0]
        if len(rows)==1 or len(cols)==1:
            mv=v; rrow=int(rows[0]); ccol=int(cols[0])
    patv=[int(v) for v in vals if int(v) not in (bg,mv)][0]
    pts=[tuple(map(int,np.argwhere(inp==patv)[i])) for i in range(len(np.argwhere(inp==patv)))]
    def oidx(p,l): return p if p<l else p-1   # coords in new grid (line removed)
    out=np.full((H-1,W-1),bg,dtype=int)
    for r,c in pts:
        for sr in {r, 2*rrow-r}:
            for sc in {c, 2*ccol-c}:
                orow=oidx(sr,rrow); ocol=oidx(sc,ccol)
                if 0<=orow<H-1 and 0<=ocol<W-1:
                    out[orow,ocol]=mv
    return out.tolist()
